UPDATE "CEI2008" SET text = 'Prima della festa di Pasqua, Gesù, sapendo che era venuta la sua ora di passare da questo mondo al Padre, avendo amato i suoi che erano nel mondo, li amò fino alla fine.' WHERE book = 50 AND chapter = 13 AND verse = 1 AND coalesce(verseequiv, '') = '' AND coalesce(verseorigin, '') = '' AND text_plain = 'Prima della festa di Pasqua Gesù, sapendo che era venuta la sua ora di passare da questo mondo al Padre, avendo amato i suoi che erano nel mondo, li amò fino alla fine.';  -- Gv 13:1
