UPDATE "CEI2008" SET text = 'Gesù le disse: "Non mi trattenere, perché non sono ancora salito al Padre; ma va'' dai miei fratelli e di'' loro: "Salgo al Padre mio e Padre vostro, Dio mio e Dio vostro".' WHERE book = 50 AND chapter = 20 AND verse = 17 AND coalesce(verseequiv, '') = '' AND coalesce(verseorigin, '') = '' AND text_plain = 'Gesù le disse: "Non mi trattenere, perché non sono ancora salito al Padre; ma va'' dai miei fratelli e di'' loro: "Salgo al Padre mio e Padre vostro, Dio mio e Dio vostro"".';  -- Gv 20:17
